import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def list_gcd(numbers):
    if not numbers:
        return 0
    return reduce(gcd, numbers)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def count_good_partitions(a):
    n = len(a)
    count = 0
    for k in range(1, n):
        A_k = a[:k]
        B_k = a[k:]

        lcm_Ak = list_lcm(A_k)
        gcd_Bk = list_gcd(B_k)

        if lcm_Ak == gcd_Bk:
            count += 1

    return count

# Test sequence A = (6, 12, 18, 36, 72, 144)
sequence_A = [6, 12, 18, 36, 72, 144]
C_6 = count_good_partitions(sequence_A)

print(f"Sequence: {sequence_A}")
print(f"Number of good partitions C(6): {C_6}")

