import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_gcd(numbers):
    if not numbers:
        return 0
    return reduce(gcd, numbers)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

# Sequence A = (6, 12, 18, 36, 72, 144)
A = [6, 12, 18, 36, 72, 144]
n = len(A)
good_partitions_count = 0

print(f"--- Verifying C(6) for A = {A} ---")

for k in range(1, n):
    A_k = A[:k]
    B_k = A[k:]

    lcm_A_k = list_lcm(A_k)
    gcd_B_k = list_gcd(B_k)

    is_good = lcm_A_k == gcd_B_k

    print(f"k={k}:")
    print(f"  A_k = {A_k}, LCM(A_k) = {lcm_A_k}")
    print(f"  B_k = {B_k}, GCD(B_k) = {gcd_B_k}")
    print(f"  Good partition? {is_good}\n")

    if is_good:
        good_partitions_count += 1

print(f"Total count C(6) for A = {A}: {good_partitions_count}")

